// TOSCANINI_UI/webapp/next.config.mjs
/**
 * TOSCANINI discovery engine — Next.js configuration.
 *
 * Static-export mode is selected by NEXT_OUTPUT=export; otherwise the dev
 * server proxies API traffic to the engine via rewrites().
 */

const ENGINE_API = process.env.ENGINE_API || "http://localhost:8000";
const EXPORT = process.env.NEXT_OUTPUT === "export";

/** @type {import('next').NextConfig} */
const nextConfig = {
  output: EXPORT ? "export" : undefined,

  /* R477 (audit bundle weight): three.js helpers in drei are barrel-exported;
     tree-shake the imports so only the pieces ModelViewer uses ship. */
  experimental: {
    optimizePackageImports: ["@react-three/drei"],
  },

  async rewrites() {
    return [
      {
        source: "/api/:path*",
        destination: `${ENGINE_API}/api/:path*`,
      },
    ];
  },
};

export default nextConfig;
